def page(title,body,active=''):
 nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if active==key else '')+f'>{label}</a>' for key,url,label in [('home','index.html','Company'),('people','staff-directory.html','Our people'),('news','updates.html','Newsroom')])
 return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{escape(title)} — NexaCorp enterprise technology, infrastructure and research."><title>{escape(title)} | NexaCorp</title><link rel="stylesheet" href="styles.css"></head>
<body><a class="skip-link" href="#main">Skip to content</a><header class="topbar"><nav class="container nav" aria-label="Main navigation"><a class="brand" href="index.html" aria-label="NexaCorp home"><span class="brand-mark" aria-hidden="true">N</span>NEXACORP<span class="brand-dot">.</span></a><div class="nav-links">{nav}</div><a class="button button-small button-secondary" href="index.html#contact">Let’s talk <span aria-hidden="true">↗</span></a></nav></header>
<main id="main">{body}</main><footer class="footer"><div class="container footer-grid"><div><a class="brand" href="index.html">NEXACORP<span class="brand-dot">.</span></a><p>Built for what comes next.</p></div><div><p class="eyebrow">Explore</p><a href="index.html#about">Our company</a><a href="staff-directory.html">Our people</a><a href="updates.html">Newsroom</a></div><div><p class="eyebrow">Get in touch</p><a href="mailto:hello@nexacorp.example">hello@nexacorp.example</a><p>Colombo · Kandy, Sri Lanka</p></div></div><div class="container footer-bottom"><span>© 2026 NexaCorp. All rights reserved.</span><span>Fictional company · ShadowNet educational lab</span></div></footer></body></html>'''
